598	    /// Physical page IDs assigned to this request, in sequence order.
599	    /// Includes every block the request currently holds — which can be one
600	    /// more than the KV tokens need (see `step_page_indices`).
601	    fn page_indices(&self) -> Vec<i32> {
602	        self.seq
603	            .inner()
604	            .assignments()
605	            .all_block_ids()
606	            .map(|&id| id as i32)
607	            .collect()
608	    }
