721	/// One full KV block a request just registered, ready to become a KV-router
722	/// store event. `sequence_hash`/`tokens_hash`/`parent_sequence_hash` are the
723	/// router's u64 hashes (`dynamo_tokens::TokenBlock` accessors, identical by
724	/// construction to what the router recomputes); `plh` is the engine's 128-bit
725	/// lineage hash, kept only to correlate an eviction event (which carries the
726	/// lineage hash) back to `sequence_hash`.
727	#[derive(Clone, Copy, Debug)]
728	pub struct RegisteredBlock {
729	    pub plh: u128,
730	    pub sequence_hash: u64,
731	    pub tokens_hash: u64,
732	    pub parent_sequence_hash: Option<u64>,
733	}
734	
735	/// Pack a kvbm [`SequenceHash`] (lineage hash) into the 16-byte content key the
736	/// offload tier addresses blocks by. Big-endian for a stable on-wire ordering.
737	fn sequence_hash_bytes(hash: &SequenceHash) -> [u8; 16] {
738	    hash.as_u128().to_be_bytes()
739	}
