888	    fn complete_non_retained_speculative_request(
889	        pool: &BlockPool,
890	        prompt: &[u32],
891	        max_output_tokens: usize,
892	    ) {
893	        const MAX_PREFILL_CHUNK: usize = 1024;
894	        const MAX_VERIFY_SPAN: usize = 17;
895	
896	        let mut request = pool.new_request(prompt.to_vec(), max_output_tokens, None);
897	        let mut prefilled = 0;
898	        while prompt.len() - prefilled > MAX_PREFILL_CHUNK {
899	            request
900	                .schedule_prefill(MAX_PREFILL_CHUNK, pool)
901	                .expect("schedule prefill chunk");
902	            request
903	                .apply_prefill_chunk(pool)
904	                .expect("apply prefill chunk");
905	            prefilled += MAX_PREFILL_CHUNK;
906	        }
907	        request
908	            .schedule_prefill(prompt.len() - prefilled, pool)
909	            .expect("schedule final prefill chunk");
910	        request
911	            .apply_prefill(70_000, pool)
912	            .expect("apply final prefill chunk");
913	
914	        while !request.is_complete() {
915	            let span = (max_output_tokens - request.generated_tokens()).min(MAX_VERIFY_SPAN);
916	            request
917	                .schedule_speculative(span, pool)
918	                .expect("schedule speculative verify");
919	            let accepted = (0..span)
920	                .map(|offset| 80_000 + offset as u32)
921	                .collect::<Vec<_>>();
922	            request
923	                .apply_speculative(&accepted, pool)
924	                .expect("apply speculative verify");
925	        }
926	
927	        request.mark_blocks_reset_on_release();
928	    }
