952	    /// kvbm's `schedule_decode` allocates the next generation block when the
953	    /// appended token fills the current block (`need = pending + 1`), so the
954	    /// raw `page_indices()` exceeds `ceil(kv_tokens / block_size)` at every
955	    /// block boundary. `step_page_indices` must hand the forward pass an
956	    /// exact page row at every step — this deadlocked Kimi DP8 on H200 when
957	    /// the raw list reached the worker's exact-match page-table check, and
958	    /// made qwen3's FlashInfer metadata read one garbage page past the
959	    /// sequence at every block boundary (#291). `prefill_view`/`decode_view`
960	    /// must carry the same exact row.
961	    #[test]
962	    fn step_page_indices_exact_at_block_boundaries() {
963	        let mut raw_overshoots = 0usize;
964	        for prompt_len in [1usize, 15, 16, 17, 31, 32, 33, 40, 47, 48] {
965	            let pool = BlockPool::new(16, 256).unwrap();
966	            let mut kv =
967	                pool.new_request((0..prompt_len as u32).map(|i| 100 + i).collect(), 24, None);
968	            kv.schedule_prefill(prompt_len, &pool).unwrap();
969	            assert_eq!(
970	                kv.step_page_indices(prompt_len).len(),
971	                prompt_len.div_ceil(16),
972	                "prefill page row P={prompt_len}"
973	            );
974	            assert_eq!(
975	                kv.prefill_view(prompt_len).num_pages(),
976	                prompt_len.div_ceil(16),
977	                "prefill view P={prompt_len}"
978	            );
979	            kv.apply_prefill(1000, &pool).unwrap();
980	            for step in 0..23u32 {
981	                kv.schedule_decode(&pool).unwrap();
982	                let need = (kv.kv_position() + 1).div_ceil(16);
983	                assert_eq!(
984	                    kv.step_page_indices(1).len(),
985	                    need,
986	                    "decode page row P={prompt_len} step={step}"
987	                );
